(()=>{
'use strict';const A=window.KingdomArt,K=window.KingdomSim,unit=A.unit,building=A.building,node=A.node,measure=A.measure,icon=A.icon,landmarks=A.landmarks,frames={},tiles={},icons={};
const make=(w,h)=>Object.assign(document.createElement('canvas'),{width:w,height:h});
function load(url){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('远征图集加载失败'));img.src=url})}
function cut(img,col,row,cols,rows,size=192){const c=make(size,size),g=c.getContext('2d');g.drawImage(img,col*img.width/cols,row*img.height/rows,img.width/cols,img.height/rows,0,0,size,size);const p=g.getImageData(0,0,size,size);for(let i=3;i<p.data.length;i+=4)if(p.data[i]<38)p.data[i]=0;g.putImageData(p,0,0);return c}
A.ready=Promise.all([A.ready,load('assets/kc-encounter.png'),load('assets/livestock.png')]).then(([,boss,animals])=>{for(const [row,key]of ['kcdragon','kcdemon'].entries())frames[key]=[0,1,2,3].map(col=>cut(boss,col,row,4,3));for(const [col,key]of ['kclair','pearl','book','armor'].entries()){tiles[key]=cut(boss,col,2,4,3);icons[key]=tiles[key].toDataURL()}for(const [row,key]of ['sheep','cow'].entries())frames[key]=[0,1,2,3].map(col=>cut(animals,col,row,4,2,112));for(const key of ['kcdragon','kcdemon'])icons[key]=frames[key][0].toDataURL();return true});
A.icon=k=>icons[k]||icon(k);A.measure=k=>['kcdragon','kcdemon','kclair'].includes(k)?{width:k==='kcdragon'?215:k==='kcdemon'?160:220,height:k==='kcdragon'?215:k==='kcdemon'?160:220}:measure(k);
function ellipse(c,x,y,rx,ry,fill,stroke){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.stroke()}}
A.unit=(c,u,time,selected)=>{if(!frames[u.kind])return K.defs[u.kind]?.monster?true:unit(c,u,time,selected);const img=frames[u.kind][Math.floor(time*(u.castUntil>time?4:1.8)+u.id)%4],w=u.kind==='kcdragon'?215:160;c.save();ellipse(c,u.x,u.y+10,w*.33,w*.11,'#1b111b55');if(selected||u.castUntil>time){c.strokeStyle=u.castUntil>time?'#f6ac5f':'#e4be75';c.lineWidth=2;ellipse(c,u.x,u.y+9,w*.32,w*.13,null,c.strokeStyle)}if(u.flash>0)c.filter='brightness(1.7)';c.translate(u.x,u.y+20+Math.sin(time*1.2)*2);if(u.facing===-1)c.scale(-1,1);c.drawImage(img,-w/2,-w,w,w);c.restore();c.font='bold 14px Georgia';c.textAlign='center';c.strokeStyle='#201717';c.lineWidth=4;c.strokeText('KC',u.x,u.y-w+12);c.fillStyle='#e6c481';c.fillText('KC',u.x,u.y-w+12);return true};
A.building=(c,b,t,selected,ghost)=>{if(b.kind!=='kclair')return building(c,b,t,selected,ghost);if(!tiles.kclair)return true;c.save();if(b.remembered)c.globalAlpha=.5;ellipse(c,b.x,b.y+15,110,33,'#211a1b66');c.drawImage(tiles.kclair,b.x-110,b.y-200,220,220);if(selected){c.lineWidth=2;ellipse(c,b.x,b.y+10,110,42,null,'#dbb76f')}c.restore();return true};
A.node=(c,n,t)=>{if(!frames[n.subtype])return node(c,n,t);const w=n.subtype==='cow'?58:44,img=frames[n.subtype][Math.floor(t*.7+n.id)%4];ellipse(c,n.x+5,n.y+3,w*.35,6,'#20301a35');c.drawImage(img,n.x-w/2,n.y-w*.9,w,w);return true};
A.landmarks=(c,s,z,sim)=>landmarks(c,{...s,landmarks:(s.landmarks||[]).filter(p=>!sim||sim.explored(0,p))},z);
A.worldTerrain=(c,sim)=>{const w=sim.world,W=w.width,H=w.height,cell=48,cols=W/cell,rows=H/cell,raster=make(cols,rows),g=raster.getContext('2d'),p=g.createImageData(cols,rows),land=new Uint8Array(cols*rows);for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const i=y*cols+x,wx=x*cell+24,wy=y*cell+24,play=K.worldPlayable(w,wx,wy),wet=K.worldWater(w,wx,wy);land[i]=play&&!wet?1:0;const color=!play?[12,26,32]:wet?[49+Math.round(y/rows*4),104,119]:[116,128,76];p.data.set([...color,255],i*4)}g.putImageData(p,0,0);c.clearRect(0,0,W,H);c.imageSmoothingEnabled=true;c.drawImage(raster,0,0,W,H);const ground=make(400,400);ground.getContext('2d').drawImage(A.ground(),0,0,400,400);c.fillStyle=c.createPattern(ground,'repeat');for(let y=1;y<rows-1;y++)for(let x=1;x<cols-1;x++){const i=y*cols+x;if(land[i]&&land[i-1]&&land[i+1]&&land[i-cols]&&land[i+cols])c.fillRect(x*cell,y*cell,cell,cell)}
 c.lineCap='round';for(const cliff of w.cliffs){if(w.starts.some(p=>K.distance(p,cliff)<700)||K.distance(cliff,w.center)<400)continue;const {x,y,rx,ry}=cliff;c.fillStyle='#3d413154';ellipse(c,x+25,y+30,rx+25,ry*.65,c.fillStyle);c.beginPath();c.moveTo(x-rx,y);for(let i=0;i<=8;i++){const a=i*Math.PI/8;c.lineTo(x-Math.cos(a)*rx,y-Math.sin(a)*ry*.45-(i%2?35:10))}c.lineTo(x+rx,y+35);c.lineTo(x-rx,y+35);c.closePath();c.fillStyle='#746c56';c.fill();c.strokeStyle='#b0a382';c.lineWidth=3;c.stroke();const rock=A.tile('stone');for(let i=0;i<5;i++){const px=x+Math.sin(i*5)*rx*.7,py=y+Math.cos(i*3)*ry*.3;c.drawImage(rock,px-27,py-42,54,45)}}
 if(['coast','river'].includes(w.style))for(const y of K.map.bridges){const x=W/2+Math.sin(y/H*Math.PI*4)*100;if(K.distance({x,y},w.center)<360||w.starts.some(p=>K.distance(p,{x,y})<610))continue;const img=A.tile('bridge'),width=205;c.drawImage(img,x-width/2,y-55,width,105)}
 for(const p of w.starts){c.strokeStyle='#c3ad7942';c.lineWidth=20;c.beginPath();c.moveTo(p.x,p.y+110);const dx=w.center.x-p.x,dy=w.center.y-p.y,d=Math.hypot(dx,dy);c.lineTo(p.x+dx/d*550,p.y+dy/d*550);c.stroke()}
 c.strokeStyle='#91a77355';c.lineWidth=2;for(let i=0;i<200;i++){const x=(i*137.7)%W,y=(i*269.3)%H;if(!K.worldPlayable(w,x,y)||K.worldWater(w,x,y))continue;c.beginPath();c.moveTo(x,y);c.lineTo(x+2,y-9);c.moveTo(x+4,y);c.lineTo(x+7,y-13);c.stroke()}
 // A distinct, defensible clearing makes the neutral objective readable without adding a new large texture.
 const cc=w.objective||w.center;c.fillStyle='#82705244';ellipse(c,cc.x,cc.y,340,150,c.fillStyle);c.strokeStyle='#a78b5a5c';c.lineWidth=6;ellipse(c,cc.x,cc.y,320,140,null,c.strokeStyle);
};
let fogCanvas=null,fogRevision=-1,fogWorld=null;
A.fog=(c,sim,width=sim.world.width,height=sim.world.height)=>{if(!sim.state.fogEnabled||!sim.fog)return;const f=sim.fog;if(fogRevision!==f.revision||fogWorld!==sim){fogWorld=sim;fogRevision=f.revision;fogCanvas=make(f.cols,f.rows);const g=fogCanvas.getContext('2d'),p=g.createImageData(f.cols,f.rows);for(let i=0;i<f.visible[0].length;i++){const a=f.visible[0][i]?0:f.explored[0][i]?178:255;p.data.set([6,15,22,a],i*4)}g.putImageData(p,0,0)}c.save();c.imageSmoothingEnabled=true;c.drawImage(fogCanvas,0,0,width,height);c.restore()};
A.worldEffect=(c,f,p)=>{if(!['bossWarning','bossFire','frost','ward'].includes(f.type))return false;c.save();c.globalAlpha=1-p;if(f.type==='bossWarning'){c.lineWidth=3;ellipse(c,f.x,f.y,f.size,f.size*.5,'#e96d3b20','#ffab6a');c.strokeStyle='#ffb96b';for(let i=0;i<8;i++){const a=i*Math.PI/4+p*2;c.beginPath();c.moveTo(f.x+Math.cos(a)*f.size*.75,f.y+Math.sin(a)*f.size*.38);c.lineTo(f.x+Math.cos(a)*f.size,f.y+Math.sin(a)*f.size*.5);c.stroke()}}else if(f.type==='bossFire'){for(let i=0;i<20;i++){const q=(p+i*.033)%1,x=f.x+(f.tx-f.x)*q+Math.sin(i*9)*18,y=f.y+(f.ty-f.y)*q+Math.cos(i*5)*13;c.fillStyle=i%2?'#ee762ba0':'#ffd17db0';ellipse(c,x,y,9+q*15,5+q*8,c.fillStyle)}}else{const tint=f.type==='frost'?'#a2dcfa':'#b1dfb6';c.lineWidth=3;ellipse(c,f.x,f.y,f.size*(.3+p*.7),f.size*(.15+p*.35),null,tint);for(let i=0;i<9;i++){c.fillStyle=tint;const a=i*Math.PI*2/9;c.fillRect(f.x+Math.cos(a)*f.size*p,f.y+Math.sin(a)*f.size*p*.5,4,7)}}c.restore();return true};
})();
